package com.pratik.imagetap;
import android.content.Context;import android.graphics.*;import android.view.*;import android.widget.*;import java.util.function.*;
final class OrbitMenu extends FrameLayout {
 final BrainView brain;final LinearLayout[] destinations=new LinearLayout[4];private boolean open;private final Paint paint=new Paint(3);private final Consumer<Boolean> state;
 OrbitMenu(Context c,boolean expanded,IntConsumer navigate,Runnable presets,Consumer<Boolean> state){super(c);this.state=state;setWillNotDraw(false);setClipChildren(false);
  String[] titles={"Actions","Regions","Presets","Settings"},icons={"images","studio","presets","settings"};
  for(int i=0;i<4;i++){final int n=i;LinearLayout node=Ui.column(c);node.setGravity(Gravity.CENTER);node.setBackground(Ui.shape(c,Ui.SURFACE,Ui.LINE,22));node.setPadding(0,Ui.dp(c,8),0,Ui.dp(c,8));node.addView(new Ui.Glyph(c,icons[i],Ui.CREAM),new LinearLayout.LayoutParams(Ui.dp(c,21),Ui.dp(c,21)));TextView label=Ui.label(c,titles[i],11,Ui.TEXT);label.setGravity(Gravity.CENTER);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=Ui.dp(c,5);node.addView(label,lp);node.setFocusable(true);node.setContentDescription("Open "+titles[i]);node.setOnClickListener(v->{if(n==2)presets.run();else navigate.accept(n==0?1:n==1?2:3);});destinations[i]=node;addView(node,new FrameLayout.LayoutParams(Ui.dp(c,76),Ui.dp(c,66)));}
  brain=new BrainView(c,true);brain.setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_YES);brain.setFocusable(true);brain.setOnClickListener(v->{performHapticFeedback(HapticFeedbackConstants.VIRTUAL_KEY);setOpen(!open,true);});addView(brain,new FrameLayout.LayoutParams(Ui.dp(c,108),Ui.dp(c,108)));setOpen(expanded,false);
 }
 boolean isOpen(){return open;}
 void setOpen(boolean value,boolean animate){open=value;brain.setContentDescription(open?"Close circular navigation":"Open circular navigation");for(View node:destinations){node.animate().cancel();node.setVisibility(open?VISIBLE:GONE);node.setAlpha(1);node.setScaleX(1);node.setScaleY(1);if(open&&animate&&Ui.motion(getContext())){node.setAlpha(0);node.setScaleX(.8f);node.setScaleY(.8f);node.animate().alpha(1).scaleX(1).scaleY(1).setDuration(220).start();}}if(state!=null)state.accept(open);requestLayout();invalidate();}
 @Override protected void onLayout(boolean changed,int l,int t,int r,int b){float cx=getWidth()/2f,cy=getHeight()/2f,rad=Math.min(Ui.dp(getContext(),110),Math.min(cx-Ui.dp(getContext(),40),cy-Ui.dp(getContext(),38)));int bw=Ui.dp(getContext(),108);brain.layout((int)cx-bw/2,(int)cy-bw/2,(int)cx+bw/2,(int)cy+bw/2);for(int i=0;i<4;i++){double a=Math.toRadians(-90+i*90);int x=(int)(cx+rad*Math.cos(a)),y=(int)(cy+rad*Math.sin(a)),w=Ui.dp(getContext(),76),h=Ui.dp(getContext(),66);destinations[i].layout(x-w/2,y-h/2,x+w/2,y+h/2);}}
 @Override protected void onDraw(Canvas c){super.onDraw(c);float cx=getWidth()/2f,cy=getHeight()/2f,r=Math.min(Ui.dp(getContext(),110),Math.min(cx-Ui.dp(getContext(),40),cy-Ui.dp(getContext(),38)));paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(Ui.dp(getContext(),.7f));paint.setColor(Ui.LINE);c.drawCircle(cx,cy,r,paint);paint.setColor(open?0xff52616c:0xff233449);for(int i=0;i<4;i++){float rr=r+Ui.dp(getContext(),12);c.drawArc(cx-rr,cy-rr,cx+rr,cy+rr,i*90+14,61,false,paint);}paint.setColor(Ui.GREEN);paint.setAlpha(open?120:45);c.drawArc(cx-r,cy-r,cx+r,cy+r,202,35,false,paint);paint.setAlpha(255);}
}
